<script setup lang="ts">defineProps<{error:{statusCode?:number;statusMessage?:string;message?:string}}>();const handle=()=>clearError({redirect:'/'})</script>
<template><div class="grid min-h-screen place-items-center bg-canvas px-5"><div class="w-full max-w-md text-center"><AppLogo class="justify-center"/><p class="mt-10 text-sm font-semibold text-brand">{{ error.statusCode||500 }}</p><h1 class="mt-2 text-3xl font-bold tracking-[-0.03em]">{{ error.statusCode===404?'Page not found':error.statusCode===429?'Too many requests':'Something went wrong' }}</h1><p class="mt-3 text-sm text-text-secondary">{{ error.statusCode===404?'The page may have moved or the address may be incorrect.':error.statusCode===429?'Please wait a moment before trying again.':'The request could not be completed. No internal exception details are shown.' }}</p><button class="btn-primary mt-7" @click="handle">Return home</button></div></div></template>
